WITH RecentShipments AS (SELECT * FROM shipments WHERE delivered_date < '2025-09-23'), shipments_stats AS (SELECT carrier, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(carrier))) AS carrier_values, ROUND((100 * SUM(CASE WHEN status = 'RETURNED' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_returned FROM RecentShipments GROUP BY carrier) SELECT * FROM shipments_stats ORDER BY pct_returned DESC, carrier ASC LIMIT 10;
